const SIGNIFICANT_DIGITS: usize = 6;

pub fn format_cpp_float(value: f32) -> String {
    if value.is_nan() {
        return if value.is_sign_negative() {
            String::from("-nan")
        } else {
            String::from("nan")
        };
    }

    if value.is_infinite() {
        return if value.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }

    if value == 0.0 {
        return String::from("0");
    }

    let sign = if value.is_sign_negative() { "-" } else { "" };
    let abs_value = value.abs();
    let rounded = format!("{:.*e}", SIGNIFICANT_DIGITS - 1, abs_value);
    let (digits, exponent) = split_rounded_scientific(&rounded);

    let body = if exponent < -4 || exponent >= SIGNIFICANT_DIGITS as i32 {
        format_scientific(&digits, exponent)
    } else {
        format_fixed(&digits, exponent)
    };

    format!("{sign}{body}")
}

