    let (mantissa, exponent) = input.split_once('e').expect("scientific format");
    let digits = mantissa.chars().filter(|&ch| ch != '.').collect::<String>();
    let exponent = exponent.parse::<i32>().expect("valid exponent");
    (digits, exponent)
