fn format_scientific(digits: &str, exponent: i32) -> String {
    let mut chars = digits.chars();
    let first = chars.next().expect("at least one digit");
    let fractional = chars.collect::<String>();
    let fractional = fractional.trim_end_matches('0');

    let mut output = String::new();
    output.push(first);
    if !fractional.is_empty() {
        output.push('.');
        output.push_str(fractional);
    }
    output.push('e');
    output.push_str(&format_exponent(exponent));
    output
}

fn format_fixed(digits: &str, exponent: i32) -> String {
    if exponent >= 0 {
        let point = exponent as usize + 1;
        if point >= digits.len() {
            let mut output = digits.to_string();
            output.extend(std::iter::repeat('0').take(point - digits.len()));
            return output;
        }

        let integer_part = &digits[..point];
        let fractional_part = digits[point..].trim_end_matches('0');
        if fractional_part.is_empty() {
            integer_part.to_string()
        } else {
            format!("{integer_part}.{fractional_part}")
        }
    } else {
        let leading_zeros = (-exponent - 1) as usize;
        let mut fractional = String::with_capacity(leading_zeros + digits.len());
        fractional.extend(std::iter::repeat('0').take(leading_zeros));
        fractional.push_str(digits);

        let fractional = fractional.trim_end_matches('0');
        if fractional.is_empty() {
            String::from("0")
        } else {
            format!("0.{fractional}")
        }
    }
